data.collector.cjs:
// Read-only cgroup v2 collector for Docker runtimes whose kubelet omits CFS metrics.
const fs=require('node:fs/promises'),path=require('node:path'),http=require('node:http')
const parse=value=>Object.fromEntries(value.trim().split('\n').map(line=>line.trim().split(/\s+/)).map(([key,v])=>[key,Number(v)]))
async function collect(root='/host-cgroup/kubepods') {
 const pods=[]
 async function scan(directory,depth=0) {
  if(depth>3)return
  let entries;try{entries=await fs.readdir(directory,{withFileTypes:true})}catch{return}
  for(const entry of entries){if(!entry.isDirectory())continue
   const folder=path.join(directory,entry.name),match=/^pod([a-f0-9-]+)$/.exec(entry.name)
   if(!match){await scan(folder,depth+1);continue}
   let periods=0,throttled=0,seconds=0,available=false
   for(const child of await fs.readdir(folder,{withFileTypes:true})){
    if(!child.isDirectory()||!/^[a-f0-9]{64}$/.test(child.name))continue
    try{const values=parse(await fs.readFile(path.join(folder,child.name,'cpu.stat'),'utf8'))
     if(!Number.isFinite(values.nr_periods)||!Number.isFinite(values.nr_throttled))continue
     available=true;periods+=values.nr_periods;throttled+=values.nr_throttled;seconds+=(values.throttled_usec||0)/1e6
    }catch{}
   }
   if(available)pods.push({uid:match[1],periods,throttled,seconds})
  }
 }
 await scan(root)
 return pods
}
async function render(root){const pods=await collect(root),lines=['# TYPE s2t_cgroup_cpu_periods_total counter','# TYPE s2t_cgroup_cpu_throttled_periods_total counter','# TYPE s2t_cgroup_cpu_throttled_seconds_total counter']
 for(const p of pods)lines.push(`s2t_cgroup_cpu_periods_total{uid="${p.uid}"} ${p.periods}`,`s2t_cgroup_cpu_throttled_periods_total{uid="${p.uid}"} ${p.throttled}`,`s2t_cgroup_cpu_throttled_seconds_total{uid="${p.uid}"} ${p.seconds}`)
 return lines.join('\n')+'\n'
}
if(require.main===module)http.createServer(async(req,res)=>{if(req.url!='/metrics'){res.writeHead(404);return res.end()}try{res.writeHead(200,{'content-type':'text/plain; version=0.0.4'});res.end(await render())}catch{res.writeHead(503);res.end()}}).listen(9108,'0.0.0.0')
module.exports={parse,collect,render}

data.prometheus.yml:
global:
  scrape_interval: 5s
  evaluation_interval: 5s
scrape_configs:
  - job_name: s2t
    kubernetes_sd_configs:
      - role: pod
        namespaces: {names: [s2t-stress-20261005]}
    relabel_configs:
      - {source_labels: [__meta_kubernetes_pod_label_app], regex: 'gateway|audio-worker', action: keep}
      - {source_labels: [__meta_kubernetes_pod_phase], regex: Running, action: keep}
      - {source_labels: [__meta_kubernetes_pod_container_port_number], regex: '8787', action: keep}
      - {source_labels: [__meta_kubernetes_pod_name], target_label: pod}
      - {source_labels: [__meta_kubernetes_pod_label_app], target_label: service}
  - job_name: prometheus
    static_configs: [{targets: ['localhost:9090']}]
  - job_name: cgroups
    static_configs: [{targets: ['cgroup-exporter:9108']}]
  - job_name: grafana
    static_configs: [{targets: ['grafana:3000']}]
  - job_name: kube-state
    static_configs: [{targets: ['kube-state-metrics:8080']}]
  - job_name: postgres
    static_configs: [{targets: ['postgres-exporter:9187']}]
  - job_name: minio
    metrics_path: /minio/v2/metrics/cluster
    static_configs: [{targets: ['minio:9000']}]
  - job_name: milvus
    static_configs: [{targets: ['milvus:9091']}]
  - job_name: etcd
    static_configs: [{targets: ['etcd:2379']}]
  - job_name: mock-models
    static_configs: [{targets: ['mock-models:9090']}]
  - job_name: redis
    metrics_path: /scrape
    static_configs: [{targets: ['redis-0.redis:6379', 'redis-1.redis:6379', 'redis-2.redis:6379']}]
    relabel_configs:
      - {source_labels: [__address__], target_label: __param_target}
      - {source_labels: [__param_target], target_label: instance}
      - {target_label: __address__, replacement: 'redis-exporter:9121'}
  - job_name: sentinel
    metrics_path: /scrape
    static_configs: [{targets: ['sentinel-0.sentinel:26379', 'sentinel-1.sentinel:26379', 'sentinel-2.sentinel:26379']}]
    relabel_configs:
      - {source_labels: [__address__], target_label: __param_target}
      - {source_labels: [__param_target], target_label: instance}
      - {target_label: __address__, replacement: 'sentinel-exporter:9121'}
  - job_name: kubelet-cadvisor
    scheme: https
    authorization: {credentials_file: /var/run/secrets/kubernetes.io/serviceaccount/token}
    tls_config: {ca_file: /var/run/secrets/kubernetes.io/serviceaccount/ca.crt}
    kubernetes_sd_configs: [{role: node}]
    relabel_configs:
      - {target_label: __address__, replacement: 'kubernetes.default.svc:443'}
      - {source_labels: [__meta_kubernetes_node_name], target_label: node}
      - {source_labels: [__meta_kubernetes_node_name], target_label: __metrics_path__, replacement: '/api/v1/nodes/$1/proxy/metrics/cadvisor'}
    metric_relabel_configs:
      - {source_labels: [namespace], regex: 's2t-stress-20261005|', action: keep}
  - job_name: kubelet
    scheme: https
    authorization: {credentials_file: /var/run/secrets/kubernetes.io/serviceaccount/token}
    tls_config: {ca_file: /var/run/secrets/kubernetes.io/serviceaccount/ca.crt}
    kubernetes_sd_configs: [{role: node}]
    relabel_configs:
      - {target_label: __address__, replacement: 'kubernetes.default.svc:443'}
      - {source_labels: [__meta_kubernetes_node_name], target_label: node}
      - {source_labels: [__meta_kubernetes_node_name], target_label: __metrics_path__, replacement: '/api/v1/nodes/$1/proxy/metrics'}
  - job_name: gateway-web
    scheme: http
    metrics_path: "/metrics"
    static_configs: [{targets: ["192.168.5.2:8787"], labels: {service: gateway, pod: web-gateway}}]
  - job_name: gateway-acceptance
    static_configs: [{targets: ["monitoring-acceptance:8787"], labels: {service: acceptance, pod: synthetic-acceptance}}]

